#!/usr/bin/env node
'use strict';

// Extract 4-byte little-endian words from the LOADable segments of an ELF64
// binary and emit them as { "virtual-address": value } JSON.
//
// For PIE (ET_DYN) binaries, which have no fixed base, the loader maps the
// first LOAD segment at an arbitrary run-time address. We follow the common
// convention used by loaders/disassemblers of a 0x400000 base, so each
// address reported is: 0x400000 + (segment_vaddr - first_seg_vaddr).
//
// Usage: node extract.js <elf-file> > out.json

const fs = require('fs');

const BASE = 0x400000;          // conventional base for PIE binaries
const WORD = 4;                 // 32-bit little-endian words

function die(msg) { process.stderr.write(msg + '\n'); process.exit(1); }

function main() {
  const arg = process.argv[2];
  if (!arg) die('usage: node extract.js <elf-file>');
  let buf;
  try { buf = fs.readFileSync(arg); } catch (e) { die('cannot read ' + arg + ': ' + e.message); }
  if (buf.length < 64) die('file too small to be ELF');

  // ELF identification
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46)
    die('not an ELF file');
  if (buf[4] !== 2) die('only ELF64 supported');      // EI_CLASS = 2 (64-bit)
  if (buf[5] !== 1) die('only little-endian supported'); // EI_DATA = 1 (LE)

  const e_phoff = buf.readUInt32LE(32);
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);

  const PT_LOAD = 1;

  // Collect LOAD segments.
  const loads = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(off);
    if (p_type !== PT_LOAD) continue;
    loads.push({
      vaddr:  Number(buf.readBigUInt64LE(off + 16)),
      offset: Number(buf.readBigUInt64LE(off + 8)),
      filesz: Number(buf.readBigUInt64LE(off + 32)),
    });
  }
  if (loads.length === 0) die('no LOAD segments');

  // For PIE the first segment's vaddr is treated as the load base; the
  // reported base is BASE (0x400000). For ET_EXEC it's typically 0 already,
  // so the shift is 0 and the real vaddrs are reported directly.
  const shift = BASE - loads[0].vaddr;

  const out = {};
  for (const seg of loads) {
    for (let i = 0; i + WORD <= seg.filesz; i += WORD) {
      const vaddr = seg.vaddr + i + shift;
      const val = buf.readUInt32LE(seg.offset + i);
      out[vaddr] = val;
    }
  }

  process.stdout.write(JSON.stringify(out) + '\n');
}

main();

